  ["250008c5e959183f"] = { "Cosa sai dirmi dell'ippogrifo Sharptalon?", "." },
  ["2505aee721f2c6b5"] = { "Be', sembra che abbiamo raccolto tutto ciò che servirà all'⟦Alliance=Alleanza⟧; ora aspettiamo solo l'⟦Horde=Orda⟧. Credo che tra poco andrò a vedere se c'è un gelato di Tigule & Foror nei paraggi.", "." },
  ["2513e3218b19ea37"] = { "Questo era il Brandicenere, folle! Mentre il Flagello cominciava a materializzarsi intorno a noi, la lama di Mograine prese a brillare... a vibrare... il giovane Mograine lo avrebbe preso come il segnale per fuggire. Si gettarono su di noi con una fame come non ne avevo mai vista. Eppure...", "." },
  ["251d6343c74c3b5c"] = { "So che stavolta funzionerà... I miei ultimi 13 tentativi erano solo prove!", "." },
  ["2524e4457a3e6a1e"] = { "Salve! È un piacere conoscerti!\n\nVedo che hai un buono speciale. Dammelo e ti offrirò qualcosa in cambio.", "." },
  ["252957fa3abb34b5"] = { "Ci sei quasi, ma non ancora! Temo che prima dovrai parlare con mia sorella, Jemma. Quando ti avrà spiegato le basi, torna da me e ti mostrerò le cose succose!", "." },
  ["252bab12ebc08acf"] = { "Grazie a te ritrovo la libertà! Vendicami!", "." },
  ["252d8fe49887df17"] = { "Kagoro, esigo la tua presenza!", "." },
  ["252da15dac565383"] = { "Intruso!", "." },
  ["252fb72a10ebf4cd"] = { "Il ruolo del guerriero è proteggere. Come proteggiamo i nostri compagni in battaglia, così dobbiamo proteggere gli interessi dei Reietti.", "." },
  ["25467d934e600ad7"] = { "L'⟦Water of the Seers=Acqua dei Veggenti⟧ è pronta da bere, {name}.", "." },
  ["2548f1e62e53fa77"] = { "Hai qualcosa di interessante da vendere, Zorbin?", "." },
  ["254dd2a7ac3f71f7"] = { "Sei molto più brav<o/a> di me a forgiare, questo è certo. Anche se negherò di averlo detto, se lo racconti in giro. Dovresti andare a parlare con Therum Deepforge. Se c'è qualcuno che può insegnarti di più, è lui.", "." },
  ["25629ad2d58e52e0"] = { "Va' con le benedizioni di Al'Akir. Ma bada: chi si avvicina ai fedeli del Signore del Vento con false intenzioni affronterà presto la Sua ira.", "." },
  ["2578d91ce6c6c683"] = { "La magia attira %s!", "." },
  ["257ec981239d870b"] = { "Sto per chiudere, comprate finché potete!", "." },
  ["257f859aec74893a"] = { "⟦Sentinels=Sentinelle⟧, difendetemi!", "." },
  ["258029e806ac748e"] = { "Devi avere reputazione Osannato presso gli elfi della notte di Darnassus prima che io ti insegni a cavalcare, {class}.", "." },
  ["258304086f4e2e00"] = { "%s comincia ad assopirsi...", "." },
  ["25894f94f4e6258a"] = { "Molto bene. Puoi andare, soldato. Riposati, ma non adagiarti troppo. Kurzen non ci lascerà in pace per sempre.", "." },
  ["258b33b6ce357bab"] = { "%s fuggono mentre il potere di controllo del globo si esaurisce.", "." },
  ["25a615207903c655"] = { "Muahahahaha! Cos'è questo patetico spettacolo che vedo davanti a me? Be', che cosa aspettate? Ho fame, e avete l'aria di un antipasto passabile!", "." },
  ["25a901f44a6d8495"] = { "%s porta le scaglie di indurium alla sua forgia.", "." },
  ["25ade7c640c11d5c"] = { "Casa tua è davvero molto lontana da qui, {race}.", "." },
  ["25bef0361211c41e"] = { "Salve, <ragazzo/ragazza>... mi chiamo Oglethorpe e potrei aver costruito io uno degli straordinari congegni gnomeschi che potresti avere! Se è esploso, allora non è opera mia; se invece ti ha reso <ricco/ricca>, possiamo parlare di diritti d'autore!\n\nAh, e se vieni da Gnomeregan, puoi prendere due angoli di novanta gradi, sbatterli insieme e metterti in marcia. Non ho niente da dirti.", "." },
  ["25c5fd0dcb51cf79"] = { "Hai sentito? Credo che si stiano avvicinando...", "." },
  ["25c6074721dc9f82"] = { "Oggetti resistenti e ben fatti in vendita vicino alla Collina! Venite tutti, nessuno escluso! Il tempo stringe, quindi sbrigatevi.", "." },
  ["25e2f74e36acd2ba"] = { "Torta di ciliegie fresca in vendita, così buona che ti farà venire le lacrime agli occhi.", "." },
  ["25e57987ae3bf6bb"] = { "Anche qui, nelle terre selvagge, cerchi il sapere. La tua sete di conoscenza è una dote ammirevole.", "." },
  ["25f42761ba1ee8e7"] = { "Ti prego, dimmi di più su Maraudon.", "." },
  ["25f97e6c6678fa9c"] = { "Ti aiuterò. Dammi le istruzioni.", "." },
